function QuestionCard({question,onAnswer,answering}){
 const [selected,setSelected]=useState([]),[reply,setReply]=useState('');
 const pending=question.status==='pending';
 if(question.business)return <section className={'question-card '+question.status}><h4>{question.prompt}</h4>{question.options.map(o=><label key={o.option_id}><input type={question.multiple?'checkbox':'radio'} name={question.id} disabled={!pending||answering} checked={selected.includes(o.option_id)} onChange={()=>setSelected(xs=>question.multiple?toggle(xs,o.option_id):[o.option_id])}/>{o.label}</label>)}{pending?<><textarea aria-label="补充回答" placeholder="也可以直接输入自己的回答" value={reply} onChange={e=>setReply(e.target.value)} disabled={answering}/><button disabled={answering||(!selected.length&&!reply.trim())} onClick={()=>onAnswer(question,{option_ids:selected,text:reply})}>提交回答</button><button disabled={answering} onClick={()=>onAnswer(question,{skip:true})}>跳过问题并继续</button></>:<p>{question.status==='skipped'?'已跳过，未选择任何答案':question.status==='answered'?'你的回答：'+question.selected_label:'问题已结束，可继续对话'}</p>}</section>;
 return <section className={'question-card '+question.status}><div className="question-kicker">{question.header||'需要你选择'}</div><h4>{question.prompt}</h4><div className="question-options">{question.options.map(option=><button key={option.option_id} disabled={!pending||answering} className={question.selected_option_id===option.option_id?'selected':''} onClick={()=>onAnswer(question,option)}><b>{option.label}</b>{option.description&&<span>{option.description}</span>}</button>)}</div>{question.status==='answered'&&<p>你的选择：{question.selected_label}</p>}{question.status==='cancelled'&&<p>本次问题已停止，未执行任何任务。</p>}{question.status==='interrupted'&&<p>问题交互已中断，请重新发送最后一条消息。</p>}</section>
}
function ChatMessage({message,legacy,questions,onAnswer,answering,onBind}){
 const presentation=message.presentation||{},assistant=message.role==='assistant';
 const waiting=questions.some(q=>q.status==='pending');
 const discussion=presentation.discussion||(message.status==='running'?'':message.text);
 const technical=[...(presentation.technical_notes||[])];
 const hasTechnical=!!(technical.length||Object.keys(message.technical||{}).length||(presentation.activity||[]).length);
 const progress=presentation.progress||{};
 const [tick,setTick]=useState(0);
 useEffect(()=>{if(message.status!=='running')return undefined;const timer=setInterval(()=>setTick(x=>x+1),1000);return()=>clearInterval(timer)},[message.status]);
 const ago=value=>{if(!value)return null;const seconds=Math.max(0,Math.round((Date.now()-new Date(value).getTime())/1000));return seconds<90?seconds+' 秒':Math.round(seconds/60)+' 分钟'};
 const stalled=message.status==='running'&&progress.last_activity&&(Date.now()-new Date(progress.last_activity).getTime())>420000;
 const progressLine=message.status==='running'&&progress.tool_calls!=null?<p className="message-status">已运行 {ago(progress.started_at)||'—'} · 最近活动 {ago(progress.last_activity)||'刚刚'}前 · 工具 {progress.tool_calls} 次（失败 {progress.failed_calls||0}）{progress.current_tool?' · 当前：'+progress.current_tool:''}{stalled?' · 仍在工作，可能较慢':''}</p>:null;
 const label=waiting?'等待选择':message.status==='running'?'正在回复':message.status==='failed'?'需要处理':message.status==='interrupted'?'已停止':'';
 if(legacy)return <div className={'message '+message.role}><div className="message-name">{message.role==='user'?'你':'Reasonix'}<span>{label}</span></div><div className="message-text"><details><summary>改造前的对话记录（展开查看）</summary>{message.text}</details></div></div>;
 const attachments=(message.events||[]).filter(x=>x.type==='attachments').flatMap(x=>x.attachments||[]);
 if(!assistant)return <div className="message user"><div className="message-name">你<span>{label}</span></div>{attachments.length>0&&<div className="message-images">{attachments.map(a=><figure key={a.id}><img alt={'图'+a.number} src={`/api/datasets/${message.dataset_id}/conversations/${message.conversation_id}/attachments/${a.id}?thumbnail=true`}/><figcaption>图{a.number}<button onClick={()=>onBind(a)}>绑定商品</button></figcaption></figure>)}</div>}<div className="message-text">{message.text}</div></div>;
 return <div className="message assistant"><div className="message-name">Reasonix<span>{label}</span></div><div className="message-business">{presentation.heading&&<div className="message-heading">{presentation.heading}</div>}{presentation.summary&&message.error_code&&<p className="message-error">{presentation.summary}</p>}{discussion?<div className="message-text">{discussion}</div>:message.status==='running'&&!waiting?<div className="message-status">正在理解当前工作表…</div>:null}{progressLine}{message.status==='running'&&(presentation.activity||[]).length>0&&<div className="message-activity" data-tick={tick}>{(presentation.activity||[]).map((item,index)=><p key={index}>{item.title}{item.status?' · '+item.status:''}</p>)}</div>}</div>{questions.map(question=><QuestionCard key={question.id} question={question} answering={answering===question.id} onAnswer={onAnswer}/>)}{hasTechnical&&<details className="operation-log"><summary>{message.error_code?'技术详情':'操作记录'}</summary>{(presentation.activity||[]).map((item,index)=><p key={index}>{item.title}{item.status?' · '+item.status:''}</p>)}{technical.map((item,index)=><pre key={index}>{item}</pre>)}{Object.keys(message.technical||{}).length>0&&<pre>{pretty(message.technical)}</pre>}</details>}</div>
}
